package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.*;import cl.nexbyte.siger.institucional.robustez.*;import cl.nexbyte.siger.institucional.notificaciones.TareasPersonales;
import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.SpringBootConfiguration;import org.springframework.boot.autoconfigure.EnableAutoConfiguration;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.context.annotation.*;import org.springframework.test.annotation.DirtiesContext;import org.springframework.test.web.servlet.MockMvc;import org.springframework.mock.web.MockHttpSession;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(classes=EquipoHttpTest.Application.class,properties={"institucional.nucleo.habilitado=true","institucional.identidad.habilitada=true"}) @AutoConfigureMockMvc @DirtiesContext
class EquipoHttpTest {
 @SpringBootConfiguration @EnableAutoConfiguration @Import({SeguridadInstitucional.class,NucleoController.class,NucleoU2Controller.class,ContinuidadU2Controller.class,EquipoCasoController.class,ErroresTecnicos.class,JsonEstricto.class,AreasHttpTest.Fixture.class})static class Application{}
 @Autowired MockMvc http;@Autowired AreasFixture f;
 MockHttpSession login(String name)throws Exception{var s=new MockHttpSession();http.perform(post("/nucleo/login").secure(true).session(s).with(csrf()).param("username",name).param("password",f.passwords.get(name))).andExpect(status().isNoContent());return s;}
 String send(MockHttpSession s,String path,Object body,int expected)throws Exception{return http.perform(post(path).secure(true).session(s).with(csrf()).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(f.d.mapper.writeValueAsString(body))).andExpect(status().is(expected)).andReturn().getResponse().getContentAsString();}
 UUID result(String s){return UUID.fromString(f.d.mapper.readTree(s).path("id").asString());}
 UUID caso(){var u=f.core.u2();var sol=u.distribuir(f.a(f.dist),UUID.randomUUID(),f.d.nuevaWeb(),new NucleoU2.Encaminar(0,new ContratosNucleo.NuevoDestino("UPR","DEMO_SEDE_A",f.headA,"AREA_A"),"Clasificación",null)).id();var q=u.asumir(f.a(f.headA),UUID.randomUUID(),sol,new NucleoU2.Asumir(0,f.profA,"Atención",null)).id();return u.abrirCaso(f.a(f.headA),UUID.randomUUID(),q,new NucleoU2.Apertura(0,f.profA,"Objetivo independiente")).id();}
 long rev(UUID c){return f.d.db.sql.queryForObject("SELECT revision FROM core_case WHERE id=?",Long.class,c.toString());}
 @Test void circuitoHttpEquipoTareaObligatoriaYCierreConNegativas()throws Exception{var c=caso();var h=login("jefe.a");var pro=login("prof.a");var other=login("prof.b");var ti=login("ti.areas");String path="/nucleo/casos/"+c+"/equipo";var r=new EquipoCaso.Incorporar(0,f.profB,"Apoyo local");http.perform(post(path).secure(true).session(h).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(f.d.mapper.writeValueAsString(r))).andExpect(status().isForbidden());send(h,path,r,400);f.otorgar(f.profB,"PROFESIONAL","AREA_A");http.perform(get("/nucleo/session").secure(true).session(other)).andExpect(status().isUnauthorized());other=login("prof.b");send(h,path,r,200);http.perform(get("/nucleo/casos/"+c).secure(true).session(other)).andExpect(status().isOk());http.perform(get(path).secure(true).session(ti)).andExpect(status().isNotFound());var t=result(send(pro,"/nucleo/casos/"+c+"/agenda",new TareasPersonales.Edicion(0,"Contactar",null,null,null,null,null,null,"CASO",c,f.profB,true,"Creador asigna tarea"),200));send(pro,"/nucleo/agenda/tareas/"+t+"/estado",new TareasPersonales.Cambio(0,"COMPLETADA",true),403);send(pro,"/nucleo/casos/"+c+"/solicitar-termino",new ContratosNucleo.Decision(rev(c),"Solicita término"),200);send(h,"/nucleo/casos/"+c+"/cerrar",new ContratosNucleo.Decision(rev(c),"Pendiente obligatoria"),409);send(other,"/nucleo/agenda/tareas/"+t+"/intentos",new TareasPersonales.Intento(0,"Contacto logrado, falta evaluación"),200);send(other,"/nucleo/agenda/tareas/"+t+"/estado",new TareasPersonales.Cambio(1,"COMPLETADA",true),200);send(h,"/nucleo/casos/"+c+"/cerrar",new ContratosNucleo.Decision(rev(c),"Revisión confirma"),200);assertEquals(0,f.d.db.sql.queryForObject("SELECT COUNT(*) FROM core_action WHERE case_id=?",Long.class,c.toString()));http.perform(get("/nucleo/agenda/tareas/"+t+"/historial").secure(true).session(other)).andExpect(jsonPath("$.length()").value(3));}
 @Test void esperaHttpSoloSeActivaPorDecisionYNoPorConsulta()throws Exception{var c=caso();var h=login("jefe.a");var pro=login("prof.a");var p=result(send(pro,"/nucleo/casos/"+c+"/espera",new EquipoCaso.Espera(0,"Informe solicitado","Contacto sintético",java.time.Instant.now().minusSeconds(10)),200));http.perform(get("/nucleo/casos/"+c+"/equipo").secure(true).session(pro)).andExpect(jsonPath("$.enEspera").value(false));send(pro,"/nucleo/casos/"+c+"/espera/"+p,new EquipoCaso.ResolverEspera(0,rev(c),"CONFIRMADA","No tiene facultad"),404);send(h,"/nucleo/casos/"+c+"/espera/"+p,new EquipoCaso.ResolverEspera(0,rev(c),"CONFIRMADA","Jefatura confirma"),200);http.perform(get("/nucleo/casos/"+c+"/equipo").secure(true).session(pro)).andExpect(jsonPath("$.enEspera").value(true));send(pro,"/nucleo/casos/"+c+"/espera/"+p,new EquipoCaso.ResolverEspera(1,rev(c),"FINALIZADA","Antecedentes recibidos y evaluados"),200);http.perform(get("/nucleo/casos/"+c).secure(true).session(pro)).andExpect(jsonPath("$.estado").value("EN_GESTION"));}
}
